function daysApart(a: string, b: string): number {
  if (a > b) [a, b] = [b, a]; // ISO strings sort like dates
  const isLeap = (y: number) => (y % 4 === 0 && y % 100 !== 0) || y % 400 === 0;
  const len = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  let [y, m, d] = a.split("-").map(Number);
  const [y2, m2, d2] = b.split("-").map(Number);
  let steps = 0;
  while (y !== y2 || m !== m2 || d !== d2) {
    d++;
    const days = len[m - 1] + (m === 2 && isLeap(y) ? 1 : 0);
    if (d > days) { d = 1; m++; }
    if (m > 12) { m = 1; y++; }
    steps++;
  }
  return steps;
}

