function daysApart(a: string, b: string): number {
  const isLeap = (y: number) => (y % 4 === 0 && y % 100 !== 0) || y % 400 === 0;
  const len = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  const dayNumber = (s: string): number => {
    const [y, m, d] = s.split("-").map(Number);
    let total = 0;
    for (let yy = 1971; yy < y; yy++) total += isLeap(yy) ? 366 : 365;
    for (let mm = 1; mm < m; mm++) total += len[mm - 1] + (mm === 2 && isLeap(y) ? 1 : 0);
    return total + d;
  };
  return Math.abs(dayNumber(a) - dayNumber(b));
